    ['q0:108'] = { a = { 'ki:626', 'qs:0:108', 'var:Quest[0][108]Prog' }, as = '2', nr = 13, ns = 7, nv = 2, p = { { e = 'Treasure Chest', g = 1, k = 'trade', x = 'Travel to Ordelle\'s Caves and hunt for an Ordelle Chest Key. Once you find a key, look for a Treasure Chest and open it. Return to Selbina and talk to the mayor. He\'ll reveal some information to you which will prove interesting to Sobane.', x0 = -112, xyz = '-111.5,28.0,-90.3', z = 193, z0 = -90 }, { c = 734, e = 'Sobane', g = 1, i = '1662', k = 'trade', x = 'Trade the tapestry to Sobane and she\'ll explain the next step.', x0 = -189, xyz = '-189.0,-2.9,99.2', z = 230, z0 = 99 }, { c = 732, e = 'Sobane', g = 1, k = 'talk', x = 'Talk to Sobane, she is willing to give you a quest, but she needs to be able to trust that you\'ll keep your mouth shut. She wants you to retrieve a Cathedral Tapestry.', x0 = -189, xyz = '-189.0,-2.9,99.2', z = 230, z0 = 99 }, { c = 736, e = 'Sobane', g = 1, k = 'talk', x = 'Return to Sobane to complete this quest and to receive your reward.', x0 = -189, xyz = '-189.0,-2.9,99.2', z = 230, z0 = 99 }, { c = 1104, e = 'Abelard', g = 1, k = 'talk', x = 'Travel to Selbina. Talk to Abelard, and he\'ll mention a diary he found, with missing pages. Perhaps his lips will loosen if you help him find them.', x0 = -52, xyz = '-52.1,-11.3,-13.1', z = 248, z0 = -13 }, { c = 1106, e = 'Abelard', g = 1, k = 'talk', x = 'Travel to Ordelle\'s Caves and hunt for an Ordelle Chest Key. Once you find a key, look for a Treasure Chest and open it. Return to Selbina and talk to the mayor. He\'ll reveal some information to you which will prove interesting to Sobane.', x0 = -52, xyz = '-52.1,-11.3,-13.1', z = 248, z0 = -13 } }, pl = '', r = 'F230:732|2=0||3|0|;F230:732|2=0||3|2|;F230:732|2=0||3|3|;F230:732|2=0||3|4|;F230:732|2=0||3|5|;F230:732|2=0||3|6|;F230:732|2=0|2=1|3|1|;F230:734|2=1,3=0|3=1|2||;F230:736|2=1,3=3|1=0,2=2,3=0|4||;F248:1104|2=1,3=1|3=2|5||;F248:1106|1=1,2=1,3=2|3=3|6||;R193:Treasure_Ches